"""runtime.llm_step: generated by the graph.py split (P1)."""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any, Callable

from ..flow import instrument
from ..runtime import flow_memory, llm, llm_config, parsing, source_visibility, stage_history, stage_services, tools as tools_mod
from ..runtime.llm import LlmResult, OpenAiTextClient
from ..runtime.stage_executor import StageExecutionRequest, StageExecutor
from ..runtime.tools import RepoToolbox
from ..state import CfuDesignState



# Rendered-prompt size above which the recorded metadata flags the call as
# oversized (chars, ~4 chars/token). Stage prompts are path-based briefs plus
# bounded evidence, so this is a regression alarm, not an expected size.
_PROMPT_WARN_CHARS = 40_000


def _llm(state: CfuDesignState) -> OpenAiTextClient:
    workdir = Path(state.get("workdir", ".")).resolve()
    config_name = state.get("llm_config") or os.environ.get("CFU_AGENT_LLM_CONFIG") or "default"
    config = llm_config.effective_config(workdir, config_name)
    # Token streaming is a run-level switch: it drives the live token log line
    # and keeps a slow generation from hitting the whole-response timeout. An
    # explicit CLI flag wins; otherwise the config's `stream` (or the default) is
    # kept as-is.
    stream = state.get("stream_llm")
    if stream is not None:
        config = {**config, "stream": bool(stream)}
    # The completion budget is a run-level switch too: an explicit
    # --max-output-tokens wins over CFU_AGENT_OUTPUT_RESERVE / the config file,
    # because a reasoning model shares that budget with its thinking tokens.
    reserve = state.get("max_output_tokens")
    if reserve:
        config = {**config, "output_reserve_tokens": int(reserve)}
    return OpenAiTextClient(state.get("model"), config=config)


def _llm_request_info(client) -> dict[str, Any]:
    return {
        "config": getattr(client, "config_name", "") or "",
        "model": getattr(client, "model", "") or "",
        "base_url": getattr(client, "base_url", "") or "",
        "api_mode": getattr(client, "api_mode", "") or "",
        "thinking": bool(getattr(client, "thinking", False)),
        "reasoning_effort": getattr(client, "reasoning_effort", None),
        "reasoning_summary": getattr(client, "reasoning_summary", None),
        "thinking_body": getattr(client, "thinking_body", None),
        "stream": bool(getattr(client, "stream", False)),
        "max_output_tokens": (getattr(client, "window_config", {}) or {}).get("output_reserve_tokens"),
        "available": bool(getattr(client, "available", False)),
    }


def _record_llm_output(
    state: CfuDesignState,
    stage: str,
    label: str,
    result: LlmResult,
    *,
    client=None,
    system: str = "",
    user: str = "",
) -> str:
    """Persist the exact returned text and the prompt that produced it.

    Both halves of the exchange are kept in the run's own audit trail so a run
    can be replayed after the prompt code changes: the answer as
    ``llm_raw/NNN.txt`` and the rendered system/user prompt as
    ``llm_raw/NNN.prompt.txt`` with a ``prompt_sha256`` in the metadata.
    """
    stage_info = {
        "ingest_input": ("ingest_input", "02_workload"),
        "analyze_workload": ("analysis", "07_analysis"),
        "design_contract": ("isa", "08_isa"),
        "extend_isa": ("isa", "08_isa"),
        "check_conformance": ("implementation", "09_implementation"),
        "implement": ("implementation", "09_implementation"),
        "route_software": ("implementation", "09_implementation"),
        "optimize": ("review", "12_review"),
    }
    artifact_stage, stage_dir = stage_info.get(stage, (None, None))
    if artifact_stage is None or stage_dir is None:
        raise ValueError(f"LLM raw output stage is not configured: {stage}")

    artifacts = stage_services._artifacts_for_stage(state, artifact_stage)
    prefix = f"{stage_dir}/llm_raw/{label}_"
    # Count only the answer files so a matching reasoning sidecar never shifts
    # the numbering of later attempts.
    existing = [
        ref for ref in artifacts.manifest.get("artifacts", [])
        if ref.get("kind") == "llm_raw_output"
        and str(ref.get("path", "")).startswith(f"{artifacts.root_rel}/{prefix}")
    ]
    index = len(existing)
    relative = f"{prefix}{index:03d}.txt"
    reasoning = str(getattr(result, "reasoning", "") or "").strip()
    metadata = {
        "llm_stage": stage,
        "llm_label": label,
        "used_llm": bool(getattr(result, "used_llm", False)),
        "input_tokens": int(getattr(result, "input_tokens", 0) or 0),
        "output_tokens": int(getattr(result, "output_tokens", 0) or 0),
        "total_tokens": int(getattr(result, "total_tokens", 0) or 0),
        "cached_input_tokens": getattr(result, "cached_input_tokens", None),
        # Observability: prove whether the provider returned reasoning at all.
        "model": str(getattr(result, "model", "") or ""),
        "api_mode_used": str(getattr(result, "api_mode_used", "") or ""),
        "finish_reason": str(getattr(result, "finish_reason", "") or ""),
        "reasoning_source": str(getattr(result, "reasoning_source", "") or ""),
        "reasoning_chars": len(reasoning),
        "response_extra_keys": list(getattr(result, "extra_keys", ()) or ()),
        # Retain provider compatibility metadata for previously recorded runs.
        "degraded_reason": str(getattr(result, "degraded_reason", "") or ""),
        # Non-empty when api_mode=auto fell back from responses to chat.
        "fallback_reason": str(getattr(result, "fallback_reason", "") or ""),
        "tool_rounds": int(getattr(result, "tool_rounds", 0) or 0),
    }
    prompt_text = ""
    if system or user:
        prompt_text = f"### SYSTEM\n{system}\n\n### USER\n{user}\n"
        metadata["prompt_sha256"] = parsing._attempt_digest(prompt_text)
        metadata["prompt_chars"] = len(prompt_text)
        if len(prompt_text) > _PROMPT_WARN_CHARS:
            # No hard budget exists yet; surface oversized prompts instead of
            # letting them grow silently until the provider rejects the call.
            metadata["prompt_oversize"] = True
    if client is not None:
        artifacts.set_manifest_metadata(artifact_stage, "llm_request", _llm_request_info(client))
    audit_path = artifacts.root / "request_audit.jsonl"
    if audit_path.is_file():
        artifacts.set_manifest_metadata(artifact_stage, "request_audit", {
            "schema_version": "1", "path": f"{artifacts.root_rel}/request_audit.jsonl",
            "format": "jsonl", "access": "host-only", "permissions": "0600",
        })  # register once; never snapshot/duplicate the growing JSONL ledger
    ref = artifacts.write_text(
        artifact_stage,
        relative,
        result.text,
        kind="llm_raw_output",
        metadata=metadata,
    )
    if prompt_text:
        # Run-local audit copy: what the model actually saw, so a replay does
        # not depend on the current prompt code being unchanged.
        artifacts.write_text(
            artifact_stage,
            f"{prefix}{index:03d}.prompt.txt",
            prompt_text,
            kind="llm_prompt",
            metadata={**metadata, "kind": "prompt"},
        )
    if reasoning:
        # Thinking is kept for audit but never parsed as the answer.
        artifacts.write_text(
            artifact_stage,
            f"{prefix}{index:03d}.reasoning.txt",
            reasoning,
            kind="llm_reasoning_output",
            metadata={**metadata, "kind": "reasoning"},
        )
    if metadata["used_llm"] and stage_history.collecting():
        try:
            stage_history.record_execution(
                state, stage_services._toolbox_for_stage(state, stage),
                stage, label, str(ref["path"]),
            )
        except (ValueError, OSError):
            pass  # Advisory history cannot turn a valid delivery into a failure.
    if instrument._PROGRESS is not None:
        instrument._LIVE_LINE.clear()
        note = ""
        if metadata["fallback_reason"]:
            note = " (streaming fell back)"
        elif metadata["degraded_reason"]:
            note = " (tools degraded)"
        print(
            f"    [llm] {label} -> in={metadata['input_tokens']} "
            f"out={metadata['output_tokens']} tok"
            f" ({metadata['api_mode_used']}, {metadata['finish_reason'] or 'n/a'}){note}",
            flush=True,
        )
    return str(ref["path"])


def _virtual_paths(state: CfuDesignState, system: str, user: str) -> tuple[str, str]:
    """Render this run's artifact root as ``{{run-dir}}`` in one request."""
    system, user = source_visibility.mask_model_payload((system, user))
    root = str(state.get("run_root", "") or "")
    if not root:
        return system, user
    return (tools_mod.virtualize_run_paths(system, root),
            tools_mod.virtualize_run_paths(user, root))


def _complete_llm(
    state: CfuDesignState,
    stage: str,
    label: str,
    system: str,
    user: str,
    fallback: str,
    response_format: dict[str, Any] | None = None,
    client=None,
) -> tuple[LlmResult, str]:
    client = client or _llm(state)
    if (state.get("flow_memory") or state.get("stage_history")
            or (state.get("run_root") and state.get("workdir"))):
        user = _with_run_memory(
            state, stage_services._toolbox_for_stage(state, stage), stage, user, label=label,
        )
    if response_format and response_format.get("type") == "json_object":
        # OpenAI-compatible gateways reject json_object mode with an opaque HTTP 400
        # when the messages never contain the word "json". Enforce the protocol here
        # so no individual prompt can reintroduce that failure.
        if "json" not in f"{system}\n{user}".lower():
            user = f"{user}\nRespond with a single JSON object and nothing else."
    # Paths are rendered with the run-directory token, so the request (and its
    # llm_raw copy) is byte-identical across runs of the same workload.
    system, user = _virtual_paths(state, system, user)
    result = llm.clean_llm_text(
        client.complete(
            system,
            user,
            fallback=fallback,
            **({"response_format": response_format} if response_format is not None else {}),
        )
    )
    raw_output = _record_llm_output(
        state, stage, label, result, client=client, system=system, user=user
    )
    if isinstance(client, OpenAiTextClient) and not result.used_llm and not state.get("dry_run", False):
        raise RuntimeError(f"{stage}: model unavailable ({getattr(result, 'fallback_reason', '') or 'no model response'}); audit={raw_output}")
    return result, raw_output


#: Argument values that carry file/oracle content rather than a selector. The
#: live log reports their size, never their text: an edit body runs to thousands
#: of lines and buries the run's own progress.
_CONTENT_ARGUMENTS = ("edits", "search", "replace", "delivery", "oracle", "content")
_MAX_LOGGED_VALUE = 60


def _short_value(value: Any, limit: int = _MAX_LOGGED_VALUE) -> str:
    """One escaped, single-line, truncated rendering of an argument value."""
    text = " ".join(str(value).split())
    return text if len(text) <= limit else text[: limit - 3] + "..."


def _edit_summary(item: Any) -> str:
    """One edit's log summary. A malformed element must never crash the CLI.

    Observed 2026-10-04 (ablation matrix, run ...-l1-isa): the model sent
    ``edits`` as a list of strings, ``item.get`` raised ``AttributeError`` in
    this live-log path, and the run died with exit code 1 and no ``status=``
    line -- the harness could only report "framework crash or launcher failure".
    """
    if not isinstance(item, dict):
        return f"<{type(item).__name__}>"
    path = str(item.get("path", "") or "").rsplit("/", 1)[-1]
    search = str(item.get("search", "") or "")
    replace = str(item.get("replace", "") or "")
    return f"{path} search={len(search)} replace={len(replace)}"


def _render_tool_arguments(name: str, arguments: dict[str, Any]) -> str:
    """A short, single-line summary of one tool call for the CLI log.

    This is presentation only: a model that sends an unexpected argument shape
    gets a plain placeholder, never an exception (the tool layer is what rejects
    malformed arguments).
    """
    if not isinstance(arguments, dict):
        return f"<{type(arguments).__name__}>"
    if name == "edit_hardware":
        edits = arguments.get("edits")
        if isinstance(edits, list):
            parts = [_edit_summary(item) for item in edits[:3]]
            if len(edits) > 3:
                parts.append(f"+{len(edits) - 3} more")
            return f"edits=[{', '.join(parts)}]"
        return "edits=?"
    if name == "edit_software":
        path = str(arguments.get("path", "") or "").rsplit("/", 1)[-1]
        search = str(arguments.get("search", "") or "")
        replace = str(arguments.get("replace", "") or "")
        return f"path={path} search={len(search)} replace={len(replace)}"
    rendered = []
    for key, value in list(arguments.items())[:4]:
        if key in _CONTENT_ARGUMENTS:
            rendered.append(f"{key}=<{len(str(value))} chars>")
        else:
            rendered.append(f"{key}={_short_value(value)}")
    return ", ".join(rendered)


def _log_tool_call(record: dict[str, Any]) -> None:
    """Print each tool call while a run is in progress (CLI log)."""
    if instrument._PROGRESS is None:
        return
    instrument._LIVE_LINE.clear()
    arguments = record.get("arguments") or {}
    rendered = _render_tool_arguments(str(record.get("name", "")), arguments)
    status = "ok" if record.get("ok") else "ERROR"
    print(
        f"    [tool] {record.get('name', '?')}({rendered}) {status} "
        f"-> {len(str(record.get('result', '')))} chars",
        flush=True,
    )


def _tool_call_summary(record: dict[str, Any]) -> dict[str, Any]:
    return {
        "round": record.get("round"),
        "tool": record.get("name"),
        "arguments": record.get("arguments"),
        "ok": record.get("ok"),
        "result_chars": len(str(record.get("result", ""))),
    }


def _write_tool_calls_artifact(
    state: CfuDesignState,
    artifact_stage: str,
    relative: str,
    tool_calls: list[dict],
) -> None:
    # Preserve the notification seam; exact read provenance is captured by
    # read_file itself. Generic tool prose belongs to this audit, not read memory.
    flow_memory.record_tool_transcript(tool_calls)
    artifacts = stage_services._artifacts_for_stage(state, artifact_stage)
    ref = artifacts.write_yaml(
        artifact_stage,
        relative,
        {
            "rounds": max((int(call.get("round", 0) or 0) for call in tool_calls), default=0),
            "call_count": len(tool_calls),
            "transcript": tool_calls,  # Exact observations, not only the display excerpt.
            "calls": [
                {**_tool_call_summary(call), "result_excerpt": str(call.get("result", ""))[:2000]}
                for call in tool_calls
            ],
        },
        status="produced",
    )
    if (stage_history.collecting() and isinstance(ref, dict)
            and any(call.get("name") == "(tool loop failed)" for call in tool_calls)):
        try:
            label = Path(relative).stem.removesuffix("_tool_calls")
            stage_history.record_execution(
                state, stage_services._toolbox_for_stage(state, artifact_stage),
                artifact_stage, label, str(ref["path"]), kind="tools",
            )
        except (ValueError, OSError):
            pass


def _tools_enabled(state: CfuDesignState, client) -> bool:
    return bool(state.get("agent_tools", True)) and getattr(client, "available", False)


def _has_delivery_block(text: str) -> bool:
    """True when the response carries an edit, file block, or patch."""
    return bool(tools_mod.extract_edit_blocks(text) or tools_mod.extract_file_blocks(text)
                or tools_mod.extract_patch(text) or re.search(r"(?m)^REPAIR_ROUTE\b", text))


# Keep the original stable system/shared user prefix intact. Reuse is a bounded
# dynamic tail, not another ever-growing conversation or a change to tool schemas.
_CONTEXT_TAIL_CHARS = 4000
_HISTORY_CHARS = 900


def _with_run_memory(state: CfuDesignState, toolbox: RepoToolbox, stage: str,
                     user: str, *, label: str = "") -> str:
    """Append version-checked file fragments and historical notes, exactly once.

    No original prompt bytes are moved or rewritten. Canonical stored paths are
    virtualized only after assembling this tail, at the model-request boundary.
    """
    if "\n\n## Run memory\n" in user or "\n\n## Stage history\n" in user:
        return user
    try:
        history = stage_history.render_history(
            state, toolbox, stage, label=label, max_chars=_HISTORY_CHARS,
        )
        history_tail = f"\n\n## Stage history\n{history}" if history else ""
        memory_header = "\n\n## Run memory\n"
        block = flow_memory.render_memory(
            flow_memory.memory_for_prompt(state, toolbox), state, toolbox,
            flow_memory.memory_stage(stage),
            max_chars=_CONTEXT_TAIL_CHARS - len(history_tail) - len(memory_header),
        )
    except (ValueError, OSError):
        return user
    memory_tail = f"{memory_header}{block}" if block else ""
    return user + memory_tail + history_tail


def _run_agent_step(
    state: CfuDesignState,
    toolbox: RepoToolbox,
    *,
    stage: str,
    label: str,
    artifact_stage: str,
    tool_calls_relpath: str,
    system: str,
    user: str,
    fallback: str,
    client=None,
    response_format: dict[str, Any] | None = None,
    deliverable_hint: str = "",
    require_delivery: bool = False,
    observation_index: dict[str, Any] | None = None,
    failure_observations: dict[str, Any] | None = None,
    toolset_factory=None,
    toolset_kwargs: dict[str, Any] | None = None,
    native_tool_loop: bool = False,
    submit_stage: Callable[[str], bool | tuple[bool, str]] | None = None,
) -> tuple[LlmResult, str, list[dict]]:
    """Compatibility facade for one stage-local model execution.

    The reusable executor owns plain/tool-loop mechanics.  This graph module
    continues to supply its existing callbacks so public test patch points and
    run artifact semantics remain stable while stages migrate incrementally.
    """
    client = client or _llm(state)
    user = _with_run_memory(state, toolbox, stage, user, label=label)
    # Virtualize LAST: dynamic memory/history contain canonical stored paths.
    system, user = _virtual_paths(state, system, user)
    executor_kwargs = dict(
        complete=_complete_llm,
        record_output=_record_llm_output,
        write_tool_calls=_write_tool_calls_artifact,
        has_deliverable=_has_delivery_block,
        on_tool_call=_log_tool_call,
    )
    if toolset_factory is not None:
        executor_kwargs["toolset_factory"] = toolset_factory
    executor = StageExecutor(**executor_kwargs)
    execution = executor.execute(
        state,
        toolbox,
        StageExecutionRequest(
            stage=stage,
            label=label,
            artifact_stage=artifact_stage,
            tool_calls_relpath=tool_calls_relpath,
            system=system,
            user=user,
            fallback=fallback,
            tools_enabled=_tools_enabled(state, client),
            response_format=response_format,
            deliverable_hint=deliverable_hint,
            require_delivery=require_delivery,
            observation_index=observation_index,
            failure_index=failure_observations,
            toolset_kwargs=toolset_kwargs,
            native_tool_loop=native_tool_loop,
            submit_stage=submit_stage,
        ),
        client=client,
    )
    return execution.result, execution.raw_output, list(execution.tool_calls)
